import {
    ChangeDetectionStrategy,
    Component,
    Inject,
    OnInit,
    ViewChild,
} from '@angular/core';
import { MAT_DIALOG_DATA } from '@angular/material/dialog';
import { UntypedFormArray, UntypedFormGroup } from '@angular/forms';
import { Observable, map, startWith } from 'rxjs';
import { I360FormBuilder } from 'app/utils/validator/form-builder';
import { I360Validators } from 'app/utils/validator/validators';
import { ModalEntry } from 'app/utils/modals/entry';
import { ModalContentComponent } from 'app/utils/modals/content/content.component';
import {
    UamPathCondition,
    UamPathsMode,
    UamRule,
    UAM_MAX_PATH_MATCHERS,
} from '@imunify360-api/uam';

export interface UamRuleDialogData {
    rule: UamRule | null;
    readonly?: boolean;
    // Nothing to offer (null or empty) means no domain enumeration on this
    // panel; degrade to a free-text input.
    domains?: string[] | null;
}

export interface UamRuleDialogResult {
    domain: string;
    cookie_ttl: string;
    label: string;
    paths?: { mode: UamPathsMode, matchers: {value: string, condition: UamPathCondition}[] } | null;
}

const TTL_PRESETS = ['10m', '30m', '1h', '4h', '12h', '24h', '72h'];
const DEFAULT_TTL = '1h';
const CUSTOM_TTL = 'custom';
const TTL_PATTERN = /^\d+[smhd]$/;
const MAX_LABEL_BYTES = 128;
const MAX_MATCHER_VALUE_BYTES = 1024;

@Component({
    templateUrl: './uam-rule-dialog.component.html',
    styleUrls: ['./uam-rule-dialog.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class UamRuleDialogComponent extends ModalEntry<UamRuleDialogData, UamRuleDialogResult>
    implements OnInit {
    readonly maxMatchers = UAM_MAX_PATH_MATCHERS;
    readonly conditions = Object.values(UamPathCondition);
    readonly modes = ['all', UamPathsMode.include, UamPathsMode.exclude];
    readonly ttlPresets = TTL_PRESETS;
    readonly customTtl = CUSTOM_TTL;
    readonly maxLabelLength = MAX_LABEL_BYTES;
    readonly maxMatcherValueLength = MAX_MATCHER_VALUE_BYTES;

    domains: string[] | null;
    filteredDomains$: Observable<string[]>;

    form: UntypedFormGroup;
    @ViewChild(ModalContentComponent, {static: true}) modalContent: ModalContentComponent;

    constructor(
        private formBuilder: I360FormBuilder,
        @Inject(MAT_DIALOG_DATA) public data: UamRuleDialogData,
    ) {
        super();
        this.domains = data.domains ?? null;
        this.form = this.buildForm();
    }

    get isEdit(): boolean {
        return !!this.data.rule;
    }

    get isReadonly(): boolean {
        return !!this.data.readonly;
    }

    get titleKey(): string {
        if (this.isReadonly) {
            return 'uam.dialog.viewTitle';
        }
        return this.isEdit ? 'uam.dialog.editTitle' : 'uam.dialog.addTitle';
    }

    get confirmKey(): string {
        return this.isEdit ? 'uam.dialog.confirmEdit' : 'uam.dialog.confirmAdd';
    }

    get subtitleKey(): string | null {
        if (!this.data.rule) {
            return null;
        }
        return this.isReadonly ? 'uam.dialog.subtitleReadonly' : 'uam.dialog.subtitle';
    }

    get subtitleParams(): {id: number, owner: string} {
        return {id: this.data.rule!.id, owner: this.data.rule!.owner};
    }

    get isCustomTtl(): boolean {
        return this.form.get('cookieTtl')!.value === CUSTOM_TTL;
    }

    get viewPathsMode(): string {
        return this.data.rule?.paths?.mode ?? 'all';
    }

    get matchers(): UntypedFormArray {
        return this.form.get('matchers') as UntypedFormArray;
    }

    ngOnInit() {
        if (this.isReadonly) {
            this.form.disable();
            return;
        }
        this.filteredDomains$ = this.form.get('domain')!.valueChanges.pipe(
            startWith(this.form.get('domain')!.value),
            map(value => this.filterDomains(value)),
        );
        this.form.get('pathsMode')!.valueChanges.subscribe(mode => {
            if (mode !== 'all' && !this.matchers.length) {
                this.addMatcher();
            }
        });
        this.form.valueChanges.subscribe(() => this.sync());
        this.sync();
    }

    addMatcher() {
        if (this.matchers.length >= this.maxMatchers) {
            return;
        }
        this.matchers.push(this.buildMatcher());
    }

    removeMatcher(index: number) {
        this.matchers.removeAt(index);
    }

    private buildForm(): UntypedFormGroup {
        const rule = this.data.rule;
        const customTtl = !!rule && !TTL_PRESETS.includes(rule.cookieTtl);
        const mode = rule?.paths ? rule.paths.mode : 'all';
        const matchers = (rule?.paths?.matchers ?? []).map(m => this.buildMatcher(m));
        const domainControl = this.formBuilder.control(
            {value: rule?.domain ?? '', disabled: !!rule},
            !rule && this.domains?.length
                ? [I360Validators.required('domain'), this.inListValidator()]
                : [I360Validators.required('domain')],
        );
        return this.formBuilder.group({
            domain: domainControl,
            cookieTtl: this.formBuilder.control(
                customTtl ? CUSTOM_TTL : (rule?.cookieTtl ?? DEFAULT_TTL),
                [I360Validators.required('cookieTtl')]),
            cookieTtlCustom: this.formBuilder.control(customTtl ? rule!.cookieTtl : ''),
            label: this.formBuilder.control(rule?.label ?? '',
                [I360Validators.maxBytes(MAX_LABEL_BYTES)]),
            pathsMode: this.formBuilder.control(mode),
            matchers: this.formBuilder.array(matchers),
        });
    }

    private buildMatcher(matcher?: {value: string, condition: UamPathCondition}): UntypedFormGroup {
        return this.formBuilder.group({
            value: this.formBuilder.control(matcher?.value ?? '',
                [I360Validators.required('value'),
                    I360Validators.maxBytes(MAX_MATCHER_VALUE_BYTES)]),
            condition: this.formBuilder.control(matcher?.condition ?? UamPathCondition.prefix),
        });
    }

    private sync() {
        this.modalContent.confirmDisabled = !this.isValid();
        this.modalContent.dialogResult = this.buildResult() as any;
    }

    private isValid(): boolean {
        if (this.form.get('domain')!.invalid || !this.resolvedTtl()) {
            return false;
        }
        if (this.isCustomTtl && !TTL_PATTERN.test(this.resolvedTtl())) {
            return false;
        }
        if (I360Validators.maxBytes(MAX_LABEL_BYTES)(this.form.get('label')!)) {
            return false;
        }
        if (this.form.get('pathsMode')!.value === 'all') {
            return true;
        }
        if (!this.matchers.length || this.matchers.length > this.maxMatchers) {
            return false;
        }
        return this.matchers.controls.every(c => {
            const value = c.get('value')!;
            return !!value.value
                && !I360Validators.maxBytes(MAX_MATCHER_VALUE_BYTES)(value);
        });
    }

    private resolvedTtl(): string {
        const raw = this.form.getRawValue();
        return raw.cookieTtl === CUSTOM_TTL
            ? (raw.cookieTtlCustom || '').trim()
            : raw.cookieTtl;
    }

    private buildResult(): UamRuleDialogResult {
        const raw = this.form.getRawValue();
        const result: UamRuleDialogResult = {
            domain: this.canonicalDomain(raw.domain) ?? raw.domain,
            cookie_ttl: this.resolvedTtl(),
            label: raw.label,
        };
        if (raw.pathsMode === 'all') {
            if (this.isEdit) {
                result.paths = null;
            }
        } else {
            result.paths = {
                mode: raw.pathsMode,
                matchers: raw.matchers,
            };
        }
        return result;
    }

    private filterDomains(value: string): string[] {
        if (!this.domains) {
            return [];
        }
        const needle = (value || '').trim().toLowerCase();
        // A typed wildcard prefix filters by the base domain and is carried
        // into the options, so picking one keeps the wildcard form.
        const prefix = this.wildcardPrefix(needle);
        const base = needle.slice(prefix.length);
        return this.domains
            .filter(domain => domain.toLowerCase().includes(base))
            .map(domain => prefix + domain);
    }

    // Hostnames are case-insensitive, but the backend compares them verbatim,
    // so the offered spelling is what has to be submitted. A wildcard of a
    // listed domain is canonicalized the same way, keeping the typed `.`/`*.`
    // prefix on the offered spelling of its base domain.
    private canonicalDomain(value: string): string | undefined {
        const needle = (value || '').trim().toLowerCase();
        const prefix = this.wildcardPrefix(needle);
        const base = this.domains?.find(
            domain => domain.toLowerCase() === needle.slice(prefix.length));
        return base === undefined ? undefined : prefix + base;
    }

    // The wildcard prefix of value ('*.' or '.'), or '' when there is none.
    private wildcardPrefix(value: string): string {
        if (value.startsWith('*.')) {
            return '*.';
        }
        return value.startsWith('.') ? '.' : '';
    }

    private inListValidator() {
        return ({value}: {value: string}) =>
            this.canonicalDomain(value) ? null : {uamDomainWildcard: {}};
    }
}
