import {
    AfterViewInit,
    ChangeDetectionStrategy,
    ChangeDetectorRef,
    Component,
    OnInit,
    ViewChild,
} from '@angular/core';
import { Observable, firstValueFrom } from 'rxjs';
import { MatSlideToggle } from '@angular/material/slide-toggle';
import { AuthState } from 'app/services/auth-state';
import { NotificationsService } from 'app/services/notifications';
import { UamService } from 'app/services/uam';
import { UamStatus } from '@imunify360-api/uam';
import { LoaderDirective } from 'app/utils/loader/loader.directive';
import { useLoader } from 'app/utils/loader/decorators';

@Component({
    selector: 'i360-webshield-uam',
    templateUrl: './webshield-uam.component.html',
    styleUrls: ['./webshield-uam.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class WebshieldUamComponent implements OnInit, AfterViewInit {
    @ViewChild('contentLoader') contentLoader: LoaderDirective;
    @ViewChild('settingsLoader') loader: LoaderDirective;

    status: UamStatus | null = null;
    // What wafd has acknowledged. The rules section reads this rather than the
    // optimistic status: mounting it early makes it fetch rules wafd still
    // rejects, and the rejection surfaces as a raw error next to the success.
    confirmedStatus: UamStatus | null = null;
    loaded = false;
    saving = false;

    constructor(
        private authState: AuthState,
        private uamService: UamService,
        private notifications: NotificationsService,
        private detector: ChangeDetectorRef,
    ) {}

    get isAdmin(): boolean {
        return this.authState.isAdmin.value;
    }

    get warningKey(): string {
        if (!this.status) {
            return 'uam.warnings.unavailable';
        }
        return this.isAdmin
            ? 'uam.warnings.serviceDisabledAdmin'
            : 'uam.warnings.serviceDisabledClient';
    }

    ngOnInit() {
        this.uamService.getStatus().subscribe(status => {
            this.status = status;
            this.confirmedStatus = status;
            this.loaded = true;
            this.contentLoader?.hide('init');
            this.detector.markForCheck();
        });
    }

    ngAfterViewInit() {
        if (!this.loaded) {
            this.contentLoader?.show('init');
        }
    }

    toggleService(source: MatSlideToggle) {
        return this.saveSetting(source, 'enabled',
            enabled => this.uamService.settingsSet({enabled}));
    }

    toggleVisibility(source: MatSlideToggle) {
        return this.saveSetting(source, 'allowed_for_users',
            allowed_for_users => this.uamService.visibilitySet({allowed_for_users}));
    }

    // The catch revert must change the bound value, or the flipped toggle's
    // self-managed state survives the failed save; [disabled]="saving" is the
    // double-click guard.
    @useLoader
    private async saveSetting(
        source: MatSlideToggle,
        key: keyof UamStatus,
        save: (value: boolean) => Observable<unknown>,
    ) {
        const value = source.checked;
        this.saving = true;
        this.status = {...this.status!, [key]: value};
        try {
            await firstValueFrom(save(value));
            this.confirmedStatus = this.status;
            this.notifications.success('uam.notifications.settingsSaved');
        } catch {
            this.status = {...this.status!, [key]: !value};
        } finally {
            this.saving = false;
            this.detector.markForCheck();
        }
    }
}
