import {
    ChangeDetectionStrategy,
    ChangeDetectorRef,
    Component,
    ElementRef,
    Input,
    OnInit,
    Renderer2,
    ViewChild,
} from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Observable, forkJoin, map, catchError, of, firstValueFrom } from 'rxjs';
import { AgentResponse, ListResponseData } from '@imunify360-api/misc';
import {
    UamRule,
    UamCounterInBackend,
    UAM_ADMIN_OWNER,
    UAM_COUNTER_PERIODS,
    UAM_DEFAULT_COUNTER_PERIOD,
    UamCounterPeriod,
} from '@imunify360-api/uam';
import { AuthState } from 'app/services/auth-state';
import { UamService } from 'app/services/uam';
import { ModalService } from 'app/utils/modals/modal.service';
import { NotificationsService } from 'app/services/notifications';
import { RequestDirective } from 'app/utils/table/request/request.directive';
import { useLoader } from 'app/utils/loader/decorators';
import {
    UamRuleDialogComponent,
    UamRuleDialogData,
    UamRuleDialogResult,
} from 'app/components/webshield/rule-dialog/uam-rule-dialog.component';

@Component({
    selector: 'webshield-rules',
    templateUrl: './webshield-rules.component.html',
    styleUrls: ['./webshield-rules.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class WebshieldRulesComponent implements OnInit {
    @Input() serviceEnabled = false;
    @Input() warningKey = 'uam.warnings.serviceDisabledAdmin';

    filterBy: 'domain' | 'owner' = 'domain';
    readonly filterFields = {
        domain: 'uam.filters.domain',
        owner: 'uam.filters.owner',
    };
    readonly periods = UAM_COUNTER_PERIODS;
    since: UamCounterPeriod = UAM_DEFAULT_COUNTER_PERIOD;

    getData = this.load.bind(this);
    @ViewChild(RequestDirective, {static: false}) request: RequestDirective;

    private domainsRequest: Promise<string[] | null> | null = null;
    private savingRules = new Set<number>();

    private readonly FLASH_TIMES = 3;
    private readonly FLASH_INTERVAL = 500;

    constructor(
        public authState: AuthState,
        private uamService: UamService,
        private modalService: ModalService,
        private notifications: NotificationsService,
        private route: ActivatedRoute,
        private router: Router,
        private el: ElementRef,
        private renderer: Renderer2,
        private detector: ChangeDetectorRef,
    ) {
        this.route.queryParams.subscribe(params => {
            this.filterBy = params['by_list'] === 'owner' ? 'owner' : 'domain';
            const since = params['since'] as UamCounterPeriod;
            this.since = UAM_COUNTER_PERIODS.includes(since)
                ? since
                : UAM_DEFAULT_COUNTER_PERIOD;
            this.detector.markForCheck();
        });
    }

    get isAdmin(): boolean {
        return this.authState.isAdmin.value;
    }

    ngOnInit() {
        this.fetchDomains();
    }

    private fetchDomains(): Promise<string[] | null> {
        if (!this.domainsRequest) {
            this.domainsRequest = firstValueFrom(this.uamService.domains())
                .then(domains => {
                    // A failed fetch must not pin the dialog to free text.
                    if (domains === null) {
                        this.domainsRequest = null;
                    }
                    return domains;
                });
        }
        return this.domainsRequest;
    }

    @useLoader
    private awaitDomains(): Promise<string[] | null> {
        return this.fetchDomains();
    }

    load(params: {[key: string]: string}): Observable<AgentResponse<ListResponseData<UamRule>>> {
        const filter = this.pickFilter(params);
        return forkJoin([
            this.uamService.list(filter),
            this.uamService.counters({...filter, since: this.since}).pipe(
                catchError(() => of(null)),
            ),
        ]).pipe(
            map(([rules, counters]) => {
                const hits = new Map(
                    (counters?.data.items ?? []).map(
                        (c: UamCounterInBackend) => [c.id, c.hits]));
                rules.data.items.forEach(rule => {
                    rule.hits = hits.get(rule.id) ?? 0;
                    rule.canManage = !this.isRowLocked(rule);
                });
                // Directive-driven fetch, no event in this view marks it dirty.
                this.detector.markForCheck();
                return rules;
            }),
        );
    }

    flashRow(ruleId: number) {
        const row = this.rowElement(ruleId);
        if (!row) {
            return;
        }
        let done = 0;
        const pulse = () => {
            this.renderer.addClass(row, 'webshield-flash');
            setTimeout(
                () => this.renderer.removeClass(row, 'webshield-flash'),
                this.FLASH_INTERVAL / 2);
            done += 1;
            if (done < this.FLASH_TIMES) {
                setTimeout(pulse, this.FLASH_INTERVAL);
            }
        };
        pulse();
    }

    private rowElement(ruleId: number): Element | null {
        const cell = this.el.nativeElement.querySelector(`[data-rule-id="${ruleId}"]`);
        return cell ? cell.closest('tr') : null;
    }

    isRowLocked(rule: UamRule): boolean {
        return this.isAdmin && rule.owner !== UAM_ADMIN_OWNER;
    }

    setSince(value: UamCounterPeriod) {
        if (value === this.since) {
            return;
        }
        this.since = value;
        // Always write the explicit value: removing the param via `since: null`
        // loses to concurrent widget navigations that rebuild the query string
        // from a pre-navigation snapshot (last write wins).
        this.router.navigate([], {
            queryParams: {since: value},
            queryParamsHandling: 'merge',
        });
        this.request?.load();
    }

    async openAdd() {
        const domains = await this.awaitDomains();
        const result = await this.modalService.open<UamRuleDialogResult, UamRuleDialogData>(
            UamRuleDialogComponent, {data: {rule: null, domains}, width: '600px'});
        if (!result) {
            return;
        }
        await this.create(result);
    }

    async openEdit(rule: UamRule) {
        const result = await this.modalService.open<UamRuleDialogResult, UamRuleDialogData>(
            UamRuleDialogComponent, {data: {rule}, width: '600px'});
        if (!result) {
            return;
        }
        await this.update(rule, result);
    }

    openView(rule: UamRule) {
        this.modalService.open<UamRuleDialogResult, UamRuleDialogData>(
            UamRuleDialogComponent, {data: {rule, readonly: true}, width: '600px'});
    }

    isRowSaving(rule: UamRule): boolean {
        return this.savingRules.has(rule.id);
    }

    async setActive(rule: UamRule, active: boolean) {
        // Disabling the toggle stops the pointer, but a focused switch keeps
        // taking keystrokes until change detection runs.
        if (this.savingRules.has(rule.id)) {
            return;
        }
        this.savingRules.add(rule.id);
        // The revert must change the bound value, or the flipped toggle's
        // self-managed state survives the failed edit (rows reuse by id).
        rule.active = active;
        try {
            await this.saveActive(rule, active);
        } catch {
            rule.active = !active;
            return;
        } finally {
            this.savingRules.delete(rule.id);
            this.detector.markForCheck();
        }
        // A failed refresh must not undo a change the server already accepted.
        await this.request.load();
    }

    async remove(rule: UamRule) {
        const confirmed = await this.modalService.confirm(
            'delete-uam-rule', [], 'true', {name: rule.domain});
        if (!confirmed) {
            return;
        }
        await this.deleteRule(rule);
    }

    @useLoader
    private async create(result: UamRuleDialogResult) {
        const {paths, ...rest} = result;
        await firstValueFrom(this.uamService.add(paths ? {...rest, paths} : rest));
        this.notifications.success('uam.notifications.ruleAdded');
        await this.request.load();
    }

    @useLoader
    private async update(rule: UamRule, result: UamRuleDialogResult) {
        const {domain, ...writable} = result;
        await firstValueFrom(
            this.uamService.edit({rule_id: rule.id, domain: rule.domain, ...writable}));
        this.notifications.success('uam.notifications.ruleUpdated');
        await this.request.load();
    }

    @useLoader
    private async saveActive(rule: UamRule, active: boolean) {
        await firstValueFrom(
            this.uamService.edit({rule_id: rule.id, domain: rule.domain, active}));
        this.notifications.success(active
            ? 'uam.notifications.ruleActivated'
            : 'uam.notifications.ruleDeactivated');
    }

    @useLoader
    private async deleteRule(rule: UamRule) {
        await firstValueFrom(this.uamService.remove({rule_id: rule.id, domain: rule.domain}));
        this.notifications.success('uam.notifications.ruleDeleted');
        await this.request.load();
    }

    private pickFilter(params: {[key: string]: string}): {domain?: string, owner?: string} {
        const filter: {domain?: string, owner?: string} = {};
        if (params['domain']) {
            filter.domain = params['domain'];
        }
        if (this.isAdmin && params['owner']) {
            filter.owner = params['owner'];
        }
        return filter;
    }
}
