import {
    ChangeDetectionStrategy,
    ChangeDetectorRef,
    Component,
    EventEmitter,
    Input,
    OnChanges,
    Output,
} from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { UamRule } from '@imunify360-api/uam';
import { UamService } from 'app/services/uam';

type TestVerdict = 'match' | 'no-match';
type TestResult = {ruleId: number, verdict: TestVerdict, domain?: string};

const TEST_URL_PATTERN =
    /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+(:\d+)?(\/\S*)?$/;

@Component({
    selector: 'webshield-test-url',
    templateUrl: './webshield-test-url.component.html',
    styleUrls: ['./webshield-test-url.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class WebshieldTestUrlComponent implements OnChanges {
    @Input() serviceEnabled = false;
    @Output() matched = new EventEmitter<number>();

    testUrl = '';
    testResult: TestResult | null = null;
    testInvalid = false;
    testing = false;

    constructor(
        private uamService: UamService,
        private detector: ChangeDetectorRef,
    ) {}

    get testDisabled(): boolean {
        return !this.serviceEnabled;
    }

    ngOnChanges() {
        // A verdict must not outlive the controls that produced it.
        if (this.testDisabled) {
            this.testResult = null;
            this.testInvalid = false;
        }
    }

    runTest(): Promise<void> {
        const url = this.testUrl.trim();
        if (this.testDisabled || !url || this.testing) {
            return Promise.resolve();
        }
        if (!TEST_URL_PATTERN.test(url.toLowerCase().replace(/^https?:\/\//, ''))) {
            this.testInvalid = true;
            this.testResult = null;
            return Promise.resolve();
        }
        this.testInvalid = false;
        this.testing = true;
        return firstValueFrom(this.uamService.test({url})).then(async response => {
            this.testResult = await this.verdictFor(response.data.rule_id);
            if (this.testResult.verdict === 'match') {
                this.matched.emit(this.testResult.ruleId);
            }
        }).catch(() => {
            this.testResult = null;
        }).finally(() => {
            this.testing = false;
            this.detector.markForCheck();
        });
    }

    onTestUrlChange() {
        this.testInvalid = false;
        this.testResult = null;
    }

    clearTest() {
        this.testUrl = '';
        this.testInvalid = false;
        this.testResult = null;
    }

    private async verdictFor(ruleId: number): Promise<TestResult> {
        if (!ruleId || ruleId < 1) {
            return {ruleId, verdict: 'no-match'};
        }
        // Only a rule the caller can list is reported: an id outside that list
        // is another owner's rule on a wafd whose test is not caller-scoped yet,
        // and the widget must not disclose it.
        const rule = await this.findRule(ruleId);
        return rule
            ? {ruleId, verdict: 'match', domain: rule.domain}
            : {ruleId: 0, verdict: 'no-match'};
    }

    private async findRule(ruleId: number): Promise<UamRule | undefined> {
        const response = await firstValueFrom(this.uamService.list({}));
        return response.data.items.find(rule => rule.id === ruleId);
    }
}
