import { ChangeDetectionStrategy, Component } from '@angular/core';
import { NAVBAR_TABS } from 'app/components/nav-root/navbar-items.enum';
import { WEBSHIELD_TABS } from 'app/components/webshield/webshield-tabs.enum';
import { isSubTabAllowed } from 'app/utils/allowed-items.utils';

@Component({
    selector: 'i360-webshield',
    templateUrl: './webshield.component.html',
    styleUrls: ['./webshield.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class WebshieldComponent {
    WEBSHIELD_TABS = WEBSHIELD_TABS;

    isTabAllowed(tab: WEBSHIELD_TABS): boolean {
        return isSubTabAllowed(NAVBAR_TABS.Webshield, tab);
    }
}
