import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { SharedModule } from 'app/core/shared.module';
import { WebshieldComponent } from 'app/components/webshield/webshield.component';
import { WEBSHIELD_TABS } from 'app/components/webshield/webshield-tabs.enum';
import {
    WebshieldUamComponent,
} from 'app/components/webshield/under-attack-mode/webshield-uam.component';
import {
    WebshieldRulesComponent,
} from 'app/components/webshield/rules/webshield-rules.component';
import {
    UamRuleDialogComponent,
} from 'app/components/webshield/rule-dialog/uam-rule-dialog.component';
import {
    WebshieldTestUrlComponent,
} from 'app/components/webshield/test-url/webshield-test-url.component';

@NgModule({
    imports: [
        CommonModule,
        SharedModule,
        RouterModule.forChild([{
            path: '',
            component: WebshieldComponent,
            children: [
                {path: '', redirectTo: WEBSHIELD_TABS.UnderAttackMode, pathMatch: 'full'},
                {path: WEBSHIELD_TABS.UnderAttackMode, component: WebshieldUamComponent},
            ],
        }]),
    ],
    declarations: [
        WebshieldComponent,
        WebshieldUamComponent,
        WebshieldRulesComponent,
        UamRuleDialogComponent,
        WebshieldTestUrlComponent,
    ],
})
export class WebshieldModule {}
